using namespace maple;
namespace fs=std::filesystem;
using json=nlohmann::json;
namespace {
struct TempRoot { fs::path path;TempRoot(){static unsigned n=0;path=fs::temp_directory_path()/("MapleRGL_chapter_save_test_"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count())+"_"+std::to_string(++n));assert(fs::create_directory(path));}~TempRoot(){std::error_code ec;auto root=fs::temp_directory_path(ec).lexically_normal();auto target=path.lexically_normal();if(!ec&&target.parent_path()==root&&target.filename().u8string().find("MapleRGL_chapter_save_test_")==0)fs::remove_all(target,ec);}};
std::string bytes(const fs::path& p){std::ifstream in(p,std::ios::binary);return {std::istreambuf_iterator<char>(in),{}};}
void write(const fs::path& p,const std::string& text){std::ofstream out(p,std::ios::binary|std::ios::trunc);assert(out);out<<text;out.close();assert(!out.fail());}
void fund(const fs::path& p){write(p/"profile.json",json{{"schema_version",0},{"crystals",1000}}.dump());}
bool close_to(double a,double b){return std::abs(a-b)<.001;}
// A deterministic legal chapter-boundary fixture; no long battle simulation or real profile.
void complete_fixture(Game& game){int cleared=game.chapter_index()+1;game.elapsed=120;game.kills=100*cleared;game.boss_spawned=game.boss_defeated=true;game.metrics.enemy_kills_by_kind.fill(0);game.metrics.enemy_kills_by_kind[int(EnemyKind::Slime)]=game.kills-cleared-1;game.metrics.enemy_kills_by_kind[int(EnemyKind::Elite)]=1;game.metrics.enemy_kills_by_kind[int(EnemyKind::Boss)]=cleared;game.metrics.chapters_cleared=cleared;game.metrics.bosses_defeated=cleared;game.metrics.skill_damage[int(Skill::Arrow)]=1000*cleared;game.metrics.damage_taken=10*cleared;game.metrics.environment_damage_taken=2*cleared;game.metrics.environment_hits=cleared;game.metrics.hazards_spawned=cleared;game.metrics.boss_spawn_time=80;game.metrics.boss_defeat_time=120;game.state=cleared==3?State::Victory:State::ChapterComplete;}
void campaign_roundtrip_and_single_rewards(){
 TempRoot t;fund(t.path);uint64_t id=0;int64_t initial=0;int paid=0,progress_paid=0;RunBonuses bonuses;RunBuild first_selected;
 {
  ProgressionStore store(t.path);assert(store.purchase(TalentId::Damage,0)&&store.purchase(TalentId::Health,0)&&store.purchase(TalentId::Reroll,0)&&store.purchase(TalentId::Reroll,1)&&store.purchase(TalentId::DeathProtection,0)&&store.purchase(TalentId::FirstEliteBonus,0));bonuses=store.run_bonuses();initial=store.profile().crystals;
  auto started=store.begin_run(CharacterClass::Archer,17,RunMode::Campaign);assert(started);id=started.run_id;Game game;game.start(CharacterClass::Archer,17,bonuses,store.profile().active_run->setup);game.coins=23;game.upgrade_rerolls_remaining=1;game.death_protections_remaining=0;game.first_elite_reward_claimed=true;game.metrics.upgrade_rerolls_used=1;game.metrics.death_protections_used=1;game.metrics.first_elite_rewards=1;complete_fixture(game);RunBuild build;assert(game.export_build(build));auto report=make_run_report(game,RunOutcome::Victory,17);auto first=store.claim_chapter(id,0,report,build);assert(first&&first.crystals_awarded>0);paid=first.crystals_awarded;progress_paid=first.progress_crystals_awarded;assert(store.profile().crystals==initial+paid&&store.profile().active_run->claimed_chapters==1&&store.profile().records.total_crystals==uint64_t(paid));
  auto saved=bytes(store.profile_path());auto duplicate=store.claim_chapter(id,0,report,build);assert(duplicate&&duplicate.already_claimed&&duplicate.crystals_awarded==0&&bytes(store.profile_path())==saved);assert(store.choose_chapter_supply(id,2));assert(store.checkpoint_build(first_selected)&&first_selected.intermission_choice==2&&first_selected.coins==38&&close_to(first_selected.next_chapter_shield_seconds,8));saved=bytes(store.profile_path());assert(store.choose_chapter_supply(id,2).already_claimed&&!store.choose_chapter_supply(id,0)&&bytes(store.profile_path())==saved);
  assert(!store.save_chapter_checkpoint(id,json{{"boundary","chapter"},{"run_id",id},{"build",{{"level",999}}}}));assert(store.profile().active_run&&store.profile().chapter_checkpoint.is_object());
 }
 {
  ProgressionStore store(t.path);RunBuild restored;assert(!store.read_only()&&store.checkpoint_build(restored));assert(restored.coins==first_selected.coins&&restored.skills==first_selected.skills&&restored.passives==first_selected.passives&&restored.upgrade_rerolls_remaining==1&&restored.death_protections_remaining==0&&restored.first_elite_reward_claimed);assert(close_to(restored.bonuses.damage_bonus,.02)&&close_to(restored.bonuses.health_bonus,4));Game game;assert(game.restore_build(restored)&&close_to(game.damage_multiplier,1.02)&&game.player.max_hp==114);assert(game.advance_chapter()&&game.chapter_index()==1&&game.coins==38&&game.upgrade_rerolls_remaining==1&&game.death_protections_remaining==0&&game.first_elite_reward_claimed);
  complete_fixture(game);RunBuild second;assert(game.export_build(second));auto second_report=make_run_report(game,RunOutcome::Victory,17);auto claim=store.claim_chapter(id,1,second_report,second);assert(claim&&claim.crystals_awarded>0);paid+=claim.crystals_awarded;progress_paid+=claim.progress_crystals_awarded;assert(progress_paid==settlement_crystals(second_report));assert(store.choose_chapter_supply(id,1)&&store.checkpoint_build(restored));assert(game.restore_build(restored)&&game.advance_chapter());complete_fixture(game);auto final_report=make_run_report(game,RunOutcome::Victory,17);int entitlement=settlement_crystals(final_report);auto finish=store.settle(id,final_report);assert(finish&&finish.progress_crystals_awarded==entitlement-progress_paid);paid+=finish.crystals_awarded;assert(store.profile().crystals==initial+paid&&!store.profile().active_run&&store.profile().chapter_checkpoint.is_null()&&store.profile().history.back().crystals==paid&&store.profile().records.total_crystals==uint64_t(paid)&&store.profile().records.total_kills==300&&store.profile().records.victories==1);auto saved=bytes(store.profile_path());assert(store.settle(id,final_report).already_claimed&&store.claim_chapter(id,1,second_report,second).already_claimed&&bytes(store.profile_path())==saved);
 }
 ProgressionStore restarted(t.path);assert(!restarted.profile().active_run&&restarted.profile().crystals==initial+paid&&restarted.profile().history.back().crystals==paid);
}
void transactional_claim_and_supply(){
 TempRoot t;ProgressionStore store(t.path);auto start=store.begin_run(CharacterClass::Archer,4,RunMode::Campaign);assert(start);Game game;game.start(CharacterClass::Archer,4,store.run_bonuses(),store.profile().active_run->setup);complete_fixture(game);RunBuild build;assert(game.export_build(build));auto report=make_run_report(game,RunOutcome::Victory,4);auto before=bytes(store.profile_path());assert(fs::create_directory(t.path/"profile.json.bak"));assert(!store.claim_chapter(start.run_id,0,report,build));assert(store.profile().crystals==0&&store.profile().active_run->claimed_chapters==0&&store.profile().chapter_checkpoint.is_null()&&bytes(store.profile_path())==before);assert(fs::remove(t.path/"profile.json.bak"));
 auto bad=report;bad.kills++;assert(!store.claim_chapter(start.run_id,0,bad,build));auto modified=build;modified.bonuses.damage_bonus=.02f;assert(!store.claim_chapter(start.run_id,0,report,modified));assert(!store.claim_chapter(start.run_id,1,report,build)&&!store.claim_chapter(start.run_id+1,0,report,build));assert(store.claim_chapter(start.run_id,0,report,build));before=bytes(store.profile_path());assert(fs::remove(t.path/"profile.json.bak")&&fs::create_directory(t.path/"profile.json.bak"));assert(!store.choose_chapter_supply(start.run_id,0));RunBuild unchanged;assert(store.checkpoint_build(unchanged)&&unchanged.intermission_choice==-1&&unchanged.vitality_levels==build.vitality_levels&&bytes(store.profile_path())==before);assert(fs::remove(t.path/"profile.json.bak"));assert(store.choose_chapter_supply(start.run_id,0)&&store.checkpoint_build(unchanged)&&unchanged.intermission_choice==0&&unchanged.vitality_levels==build.vitality_levels+1);
 ProgressionStore reader(t.path);assert(reader.read_only()&&!reader.choose_chapter_supply(start.run_id,0)&&!reader.claim_chapter(start.run_id,0,report,build));
}
void ending_after_checkpoint_keeps_awards(){
 TempRoot t;uint64_t id=0;int claimed=0;RunReport boundary;
 {
  ProgressionStore store(t.path);auto start=store.begin_run(CharacterClass::Archer,8,RunMode::Campaign);assert(start);id=start.run_id;Game game;game.start(CharacterClass::Archer,8,{},store.profile().active_run->setup);complete_fixture(game);RunBuild build;assert(game.export_build(build));boundary=make_run_report(game,RunOutcome::Victory,8);auto claim=store.claim_chapter(id,0,boundary,build);assert(claim);claimed=claim.crystals_awarded;assert(store.profile().active_run&&store.profile().chapter_checkpoint.is_object());
 }
 ProgressionStore resumed(t.path);RunBuild pending;assert(resumed.checkpoint_build(pending)&&pending.intermission_choice==-1);RunReport end=boundary;end.outcome=RunOutcome::Abandoned;auto result=resumed.settle(id,end);assert(result&&result.crystals_awarded==0&&resumed.profile().crystals==claimed&&resumed.profile().history.back().crystals==claimed&&resumed.profile().records.total_crystals==uint64_t(claimed)&&resumed.profile().chapter_checkpoint.is_null());
}
void schema_one_migration_and_invalid_snapshot(){
 TempRoot t;json old;
 {ProgressionStore seed(t.path);assert(seed.save_settings({}));old=json::parse(bytes(seed.profile_path()));}
 old["schema_version"]=1;old["crystals"]=77;old["talents"]["damage"]=1;old["user_extension"]={{"keep",true}};write(t.path/"profile.json",old.dump());
 {ProgressionStore migrated(t.path);assert(migrated.load_state()==ProfileLoadState::Migrated&&migrated.profile().crystals==77&&migrated.talent_rank(TalentId::Damage)==1);assert(migrated.save_settings(migrated.profile().settings));auto current=json::parse(bytes(migrated.profile_path()));assert(current["schema_version"]==profile_schema_version&&current["user_extension"]==old["user_extension"]);auto run=migrated.begin_run(CharacterClass::Archer,5,RunMode::Campaign);Game game;game.start(CharacterClass::Archer,5,migrated.run_bonuses(),migrated.profile().active_run->setup);complete_fixture(game);RunBuild build;assert(game.export_build(build)&&migrated.claim_chapter(run.run_id,0,make_run_report(game,RunOutcome::Victory,5),build));assert(migrated.save_settings(migrated.profile().settings));}
 auto bad=json::parse(bytes(t.path/"profile.json"));bad["chapter_checkpoint"]["build"]["skills"][Game::skill_key(Skill::Homing)]=5;write(t.path/"profile.json",bad.dump());ProgressionStore restored(t.path);assert(restored.load_state()==ProfileLoadState::RecoveredBackup);RunBuild valid;assert(restored.checkpoint_build(valid)&&valid.skills[int(Skill::Homing)]==0);
}
}
int main(){campaign_roundtrip_and_single_rewards();transactional_claim_and_supply();ending_after_checkpoint_keeps_awards();schema_one_migration_and_invalid_snapshot();std::cout<<"chapter_save: schema migration, atomic claims, one-time supplies, boundary restart, pinned bonuses, cumulative settlement and rollback passed (isolated roots only)\n";}
